'use strict';
const fs=require('fs'),path=require('path'),Module=require('module'),crypto=require('crypto');
const snap=JSON.parse(fs.readFileSync(path.join(__dirname,'snapshots.json'),'utf8'));
const mode=process.argv[2],test=process.argv[3],source={...snap.snapshots[mode],...snap.inputs},read=fs.readFileSync;
const key=f=>path.relative(snap.root,Buffer.isBuffer(f)?f.toString():f).replace(/\\/g,'/');
fs.readFileSync=function(f,o){const p=key(f);if(Object.hasOwn(source,p)){const encoding=typeof o==='string'?o:o?.encoding;return encoding?Buffer.from(source[p]).toString(encoding):Buffer.from(source[p]);}return read.apply(this,arguments);};
for(const ext of ['.js','.cjs']){const original=Module._extensions[ext]||Module._extensions['.js'];Module._extensions[ext]=(m,f)=>{const p=key(f);if(Object.hasOwn(source,p))m._compile(source[p],f);else original(m,f);};}
const simplify=x=>typeof x==='string'&&x.length>2000?{length:x.length,sha256:crypto.createHash('sha256').update(x).digest('hex'),prefix:x.slice(0,300),suffix:x.slice(-300)}:x;
process.on('uncaughtExceptionMonitor',e=>process.stderr.write('\nFREEZE_ASSERTION_EVIDENCE '+JSON.stringify({name:e.name,code:e.code,operator:e.operator,actual:simplify(e.actual),expected:simplify(e.expected),stack:e.stack?.slice(0,1200)})+'\n'));
const entry=path.join(snap.root,test);process.argv=[process.execPath,entry];Module._load(entry,null,true);

